SELECT *
FROM lc_quotes


        AND quote_no LIKE CONCAT('%', #{quoteNo}, '%')


        AND customer_name LIKE CONCAT('%', #{customerName}, '%')


        AND status = #{status}


        AND total_amount >= #{minPrice}


        AND total_amount <= #{maxPrice}


        AND ext4 LIKE CONCAT('%', #{projectName}, '%')


ORDER BY id DESC

SELECT COUNT(id)
FROM lc_quotes


        AND quote_no LIKE CONCAT('%', #{quoteNo}, '%')


        AND customer_name LIKE CONCAT('%', #{customerName}, '%')


        AND status = #{status}


        AND total_amount >= #{minPrice}


        AND total_amount <= #{maxPrice}


        AND ext4 LIKE CONCAT('%', #{projectName}, '%')
